  z.string(),
  z.number(),
  {
    decode: Number,
    encode: String,
  }
);

const numberToString = stringToNumber.invert();
```

However, this doesn’t accurately show how the new API works, since during the review process of #5770 it was changed from `codec.invert()` to `z.invertCodec(codec)`.

